examples.code:
MonarchCombobox(
    "Tag",
    selection: $tag,
    options: tags,
    onCreate: { text in
        let option = MonarchComboboxOption(id: text.lowercased(), label: text)
        tags.append(option)
        return option
    }
)

MonarchCombobox(
    "Language",
    selection: $language,
    options: [
        MonarchComboboxOption(id: "de", label: "Deutsch", hint: "German", leadingText: "🇩🇪", labelLanguage: Locale.Language(identifier: "de")),
        MonarchComboboxOption(id: "ja", label: "日本語", hint: "Japanese", leadingText: "🇯🇵", labelLanguage: Locale.Language(identifier: "ja")),
    ],
    loadError: loadError,
    onRetry: { loadError = nil }
)
